{
  "slug": "tallyprime-company-selection-checklist",
  "title": "Choosing the Right TallyPrime Company Before Syncing",
  "description": "Identify the correct company when similar names, separate branches or old copies appear in TallyPrime.",
  "category": "Setup",
  "sections": [
    {
      "heading": "Confirm the books with your team",
      "body": "Ask the person responsible for the books which company should feed Syncora. Record the exact name and one transaction they recognize in that company. A year in the name or a familiar spelling can be helpful, but the actual entry is the stronger check."
    },
    {
      "heading": "Use a voucher as a fingerprint",
      "body": "Open the intended company and find the sample voucher. Confirm its type and date before starting the connector. If another company uses the same voucher number, match the party and amount as well."
    },
    {
      "heading": "Check the company after sign-in",
      "body": "Open the synced company in Syncora and locate the reference entry. If two similar companies are available, read the selected company name again before exporting any report. Share the exact names and reference entry with your accountant if you still cannot tell which copy is current."
    }
  ],
  "relatedPaths": [
    "/guides/tallyprime-setup",
    "/product-overview"
  ]
}
